function updateVisibility(){const checks={'tx-gaussian':['gaussian','super_gaussian'].includes(draft.optics.tx_model),'tx-super':draft.optics.tx_model==='super_gaussian','tx-dataset':draft.optics.tx_model==='dataset','rx-gaussian':['gaussian_psf','super_gaussian_psf'].includes(draft.optics.rx_model),'rx-super':draft.optics.rx_model==='super_gaussian_psf','rx-synthetic':draft.optics.rx_model!=='dataset','rx-dataset':draft.optics.rx_model==='dataset','aperture-axes':draft.optics.rx_aperture_shape!=='circle','aperture-circle':draft.optics.rx_aperture_shape==='circle','solar':draft.optics.solar_enabled,'no-solar':!draft.optics.solar_enabled,'pixel-pitch':draft.optics.rx_model!=='dataset','ambient':draft.optics.other_light_enabled,'no-ambient':!draft.optics.other_light_enabled};document.querySelectorAll('[data-visible]').forEach(el=>el.classList.toggle('hidden',!checks[el.dataset.visible]));const mode=draft.readout.readout_mode;const active={tdc_count:mode==='shared_multitdc',tdc_max_hits_per_cycle:!['independent_first','shared_first'].includes(mode),or_pulse_width_ns:mode.startsWith('shared'),coincidence_window_ns:mode.startsWith('coincidence'),coincidence_threshold:mode.startsWith('coincidence')};for(const [key,shown]of Object.entries(active)){const input=document.querySelector(`[data-path="readout.${key}"]`);if(input)input.closest('label').classList.toggle('hidden',!shown);}}
