 $('toScan').onclick=async()=>{try{const saved=localStorage.getItem('spad-columns-v4'),current=saved?JSON.parse(saved).experiment:{};const value=await request('/api/columns/from-system',{system:canonical(collect()),current});sessionStorage.setItem('lidar-system-to-columns',JSON.stringify(value));location.href='/system/scan';}catch(error){setError(error);}};
